fn count(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.count) {
        return;
    }
    let bin = values[i] * params.bins / 1000u;
    atomicAdd(&bins[bin], 1u);
}
"#;

struct Job {
    count: u32,
    seed: u32,
    bins: u32,
}

fn read_job(path: &str) -> Result<Job, String> {
    let text = std::fs::read_to_string(path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let fields: Vec<&str> = text.split_whitespace().collect();
    let [count, seed, bins] = fields[..] else {
        return Err(format!("expected '<count> <seed> <bins>' in {path}"));
    };
    let parse = |s: &str, name: &str| -> Result<u32, String> {
        s.parse::<u32>().map_err(|e| format!("bad {name} '{s}': {e}"))
    };
    let job = Job {
        count: parse(count, "count")?,
        seed: parse(seed, "seed")?,
        bins: parse(bins, "bins")?,
    };
    if job.count > 4_000_000 || job.seed > 9999 || !(1..=MAX_BINS).contains(&job.bins) {
        return Err("parameters out of range".to_string());
    }
    Ok(job)
}

fn run(job: &Job) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle());
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions {
        power_preference: wgpu::PowerPreference::HighPerformance,
        ..Default::default()
    }))
    .map_err(|e| format!("no GPU adapter: {e}"))?;
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default()))
        .map_err(|e| format!("cannot open GPU device: {e}"))?;

    let params: Vec<u8> = [job.count, job.seed, job.bins, 0]
        .iter()
        .flat_map(|v| v.to_le_bytes())
        .collect();
    let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: &params,
        usage: wgpu::BufferUsages::UNIFORM,
    });

    // Buffers cannot be empty, so a zero count still gets one slot.
    let values_buf = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("values"),
        size: u64::from(job.count.max(1)) * 4,
        usage: wgpu::BufferUsages::STORAGE,
        mapped_at_creation: false,
    });
    let bins_size = u64::from(MAX_BINS) * 4;
    let bins_buf = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("bins"),
        size: bins_size,
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size: bins_size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("histogram"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });

    let storage = |binding: u32, read_only: bool| wgpu::BindGroupLayoutEntry {
        binding,
        visibility: wgpu::ShaderStages::COMPUTE,
        ty: wgpu::BindingType::Buffer {
            ty: wgpu::BufferBindingType::Storage { read_only },
            has_dynamic_offset: false,
            min_binding_size: None,
        },
        count: None,
    };
    let layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("histogram layout"),
        entries: &[
            wgpu::BindGroupLayoutEntry {
                binding: 0,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Uniform,
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            },
            storage(1, false),
            storage(2, false),
        ],
    });
    let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
        label: Some("histogram pipeline layout"),
        bind_group_layouts: &[Some(&layout)],
        immediate_size: 0,
    });
    let pipeline = |entry: &str| {
        device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some(entry),
            layout: Some(&pipeline_layout),
            module: &module,
            entry_point: Some(entry),
            compilation_options: Default::default(),
            cache: None,
        })
    };
    let generate = pipeline("generate");
    let count = pipeline("count");

    let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("histogram bindings"),
        layout: &layout,
        entries: &[
            wgpu::BindGroupEntry {
                binding: 0,
                resource: params_buf.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 1,
                resource: values_buf.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 2,
                resource: bins_buf.as_entire_binding(),
            },
        ],
    });

    let groups = job.count.div_ceil(WORKGROUP_SIZE);
    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
        label: Some("histogram"),
    });
    if groups > 0 {
        for (label, p) in [("generate", &generate), ("count", &count)] {
            let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
                label: Some(label),
                ..Default::default()
            });
            pass.set_pipeline(p);
            pass.set_bind_group(0, &bind_group, &[]);
            pass.dispatch_workgroups(groups, 1, 1);
        }
    }
    encoder.copy_buffer_to_buffer(&bins_buf, 0, &readback, 0, bins_size);
    queue.submit(Some(encoder.finish()));

    let slice = readback.slice(..);
    let (tx, rx) = mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |result| {
        let _ = tx.send(result);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("GPU poll failed: {e}"))?;
    rx.recv()
        .map_err(|e| format!("map callback lost: {e}"))?
        .map_err(|e| format!("cannot map readback buffer: {e}"))?;

    let data = slice.get_mapped_range();
    let bins: Vec<u32> = data
        .chunks_exact(4)
        .map(|c| u32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .take(job.bins as usize)
        .collect();
    drop(data);
    readback.unmap();
    Ok(bins)
}

fn main() -> ExitCode {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: gpu_histogram <job-file>");
        return ExitCode::FAILURE;
    };
    let job = match read_job(&path) {
        Ok(job) => job,
        Err(e) => {
            eprintln!("error: {e}");
            return ExitCode::FAILURE;
        }
    };
    let bins = match run(&job) {
        Ok(bins) => bins,
        Err(e) => {
            eprintln!("error: {e}");
            return ExitCode::FAILURE;
        }
    };
    for (index, n) in bins.iter().enumerate() {
        println!("BIN {index} {n}");
    }
    println!("TOTAL {}", job.count);
    ExitCode::SUCCESS
}
